fn send_cmd(&self, cmd: Command) -> Result<()> {
    let cmd_name = cmd.to_string();

    // First, send to the flume channel.
    self.sender.try_send(cmd).map_err(|e| match e {
        TrySendError::Full(_) => Error::Again,
        TrySendError::Disconnected(_) => Error::DaemonShutdown,
    })?;

    // Second, send a signal to notify the daemon.
    let addr = SocketAddrV4::new(LOOPBACK_V4, 0);
    let socket = UdpSocket::bind(addr)
        .map_err(|e| e_fmt!("Failed to create socket to send signal: {}", e))?;
    socket
        .send_to(cmd_name.as_bytes(), self.signal_addr)
        .map_err(|e| {
            e_fmt!(
                "signal socket send_to {} ({}) failed: {}",
                self.signal_addr,
                cmd_name,
                e
            )
        })?;

    Ok(())
}

pub struct LimitedBrowse {
    // The standard subscription channel supplies identity and lifetime only.
    // Its single SearchStarted event is never used for state delivery.
    lifetime: Receiver<ServiceEvent>,
    state: Arc<Mutex<LimitedServiceState>>,
}

#[derive(Debug)]
struct LimitedServiceState {
    limit: usize,
    dirty: bool,
    services: BTreeMap<String, ResolvedService>,
}

impl LimitedBrowse {
    /// Returns the latest complete selected view after a change. Intermediate
    /// updates coalesce; removals are represented by absence in the next view.
    /// A caller must replace its prior view, rather than merge snapshots.
    pub fn take_snapshot(&self) -> Option<Vec<ResolvedService>> {
        let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
        if !state.dirty {
            return None;
        }
        let snapshot = state.services.values().cloned().collect();
        state.dirty = false;
        Some(snapshot)
    }

    /// A closed view must be discarded; it can no longer report removals.
    pub fn is_closed(&self) -> bool {
        self.lifetime.is_disconnected()
    }
}

/// `limit` must be in 1..=64. Updates coalesce even if the caller pauses.
/// Removal frees a slot for a later resolved service; there is no waiting list
/// or automatic refill from the unselected cache. Replaces any browse of the
/// same service type. Uses the same errors as [`browse`](Self::browse).
/// This does not bound DNS records, timers, or pending resolution work.
pub fn browse_limited(&self, service_type: &str, limit: usize) -> Result<LimitedBrowse> {
    check_domain_suffix(service_type)?;
    if !(1..=64).contains(&limit) {
        return Err(e_fmt!("limited browse requires 1..=64 services"));
    }
    let state = Arc::new(Mutex::new(LimitedServiceState {
        limit,
        dirty: true,
        services: BTreeMap::new(),
    }));
    let (sender, lifetime) = bounded(1);
    self.send_cmd(Command::BrowseLimited(
        service_type.to_string(),
        sender,
        state.clone(),
    ))?;
    Ok(LimitedBrowse { lifetime, state })
}

fn remove_service_subscription(&mut self, ty_domain: &str) -> Option<Sender<ServiceEvent>> {
    let sender = self.service_queriers.remove(ty_domain);
    self.limited_browses.remove(ty_domain);
    self.clear_service_retransmissions(ty_domain);
    sender
}

fn remove_hostname_subscription(
    &mut self,
    hostname: &str,
) -> Option<(Sender<HostnameResolutionEvent>, Option<Instant>)> {
    let key = hostname.to_lowercase();
    let entry = self.hostname_resolvers.remove(&key);
    self.clear_hostname_retransmissions(&key);
    entry
}

fn service_live(&self, ty_domain: &str, sender: &Sender<ServiceEvent>) -> bool {
    self.service_queriers
        .get(ty_domain)
        .is_some_and(|s| s.same_channel(sender))
}

fn push_service(&mut self, ty_domain: &str, event: ServiceEvent) {
    let Some(sender) = self.service_queriers.get(ty_domain).cloned() else {
        return;
    };
    if let Some(state) = self.limited_browses.get(ty_domain) {
        if sender.is_disconnected() {
            self.remove_service_subscription(ty_domain);
            return;
        }

let started = ServiceEvent::SearchStarted(format!(
    "{ty} on {} interfaces [{}]",
    pretty_addrs.len(),
    pretty_addrs.join(", ")
));
