    // If there is already a `listener`, it will be updated, i.e. overwritten.
    self.service_queriers.insert(ty.clone(), listener.clone());
    let now = Instant::now();
    self.query_cache_for_service(&ty, &listener, now);
    if !self.service_live(&ty, &listener) {
        return;
    }
